import{_ as n,a,b as t}from"./chunks/bubbles-03.CRJ58gUA.js";import{_ as i,o as r,c as s,a3 as l}from"./chunks/framework.D1iekJsc.js";const m=JSON.parse('{"title":"Blasen und Eingabe","description":"MiniTavern Blasen- und Eingabestil — Thema folgen oder Hintergrund, Ecken, Erzählung / Aktion / Gesprochenes und Weichzeichner selbst setzen.","frontmatter":{"title":"Blasen und Eingabe","description":"MiniTavern Blasen- und Eingabestil — Thema folgen oder Hintergrund, Ecken, Erzählung / Aktion / Gesprochenes und Weichzeichner selbst setzen.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"Blasen und Eingabe · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Blasen- und Eingabestil — Thema folgen oder Hintergrund, Ecken, Erzählung / Aktion / Gesprochenes und Weichzeichner selbst setzen."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de/manual/bubbles"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de/manual/bubbles"}]]},"headers":[],"relativePath":"de/manual/bubbles.md","filePath":"de/manual/bubbles.md","lastUpdated":1791862671000}'),o={name:"de/manual/bubbles.md"};function h(d,e,u,g,c,b){return r(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="blasen-und-eingabe" tabindex="-1">Blasen und Eingabe <a class="header-anchor" href="#blasen-und-eingabe" aria-label="Permalink to &quot;Blasen und Eingabe&quot;">​</a></h1><p>Pfad: unten <strong>Einstellungen</strong> → <strong>Chat-Einstellungen</strong> → <strong>Blasen und Eingabe</strong>.</p><p>Diese Seite ändert das Chat-Aussehen für die ganze App. Design und Schriftgröße bleiben unter <strong>Einstellungen → Design und Schrift</strong>.</p><h2 id="schritte" tabindex="-1">Schritte <a class="header-anchor" href="#schritte" aria-label="Permalink to &quot;Schritte&quot;">​</a></h2><div class="shot-flow"><figure class="shot-step"><img src="'+n+'" alt="Einstellungen"><figcaption>1 · Einstellungen → Chat-Einstellungen</figcaption></figure><figure class="shot-step"><img src="'+a+'" alt="Blasen und Eingabe in den Chat-Einstellungen"><figcaption>2 · Blasen und Eingabe</figcaption></figure><figure class="shot-step"><img src="'+t+'" alt="Blasenfarben und Eckenradius"><figcaption>3 · Thema folgen aus, dann anpassen</figcaption></figure></div><h2 id="blasen" tabindex="-1">Blasen <a class="header-anchor" href="#blasen" aria-label="Permalink to &quot;Blasen&quot;">​</a></h2><p><strong>Blase</strong> und <strong>Eingabe</strong> haben jeweils <strong>Thema folgen</strong>. An verwendet das aktuelle Thema. Aus lässt die Einstellungen darunter das Thema überschreiben; leere Farben nutzen weiter das Thema.</p><ol><li><strong>KI-Blase</strong> und <strong>Eigene Blase</strong>: Farbkreis. Preset-Farben sind Kreise und zeigen bei Auswahl ein Häkchen. Deckkraft und Farbwert lassen sich ändern, der Wert lässt sich kopieren. Steht in der Zeile „Designfarbe verwenden“, folgt dieser Punkt dem Thema.</li><li><strong>Eckenradius</strong>: höhere Werte sind runder. Nach dem Ziehen gilt diese Zahl statt des Thema-Abstands.</li><li>Textfarben sind getrennt: <ul><li><strong>Erzählungstext</strong> und Erzählungshintergrund: normaler Text und Fett</li><li><strong>Aktion</strong>: Text in <code>*Sternchen*</code></li><li><strong>Gesprochenes</strong>: Text in Anführungszeichen</li><li>innerer Gedanke</li></ul></li><li>Nutzt eine Karte diese Zeichen nicht, bleibt der Text sichtbar, im Erzählungsstil. Volle HTML-Karten behalten ihre eigenen Farben.</li></ol><h2 id="eingabe" tabindex="-1">Eingabe <a class="header-anchor" href="#eingabe" aria-label="Permalink to &quot;Eingabe&quot;">​</a></h2><p><strong>Thema folgen</strong> der Eingabe aus schalten, dann Hintergrund, Eckenradius, Platzhalter, Text, Schaltflächensymbole und <strong>Weichzeichner</strong> ändern.</p><p>Mit Weichzeichner lassen sich Farbton und Stärke einstellen. Android unter API 31 hat keinen Schalter. Unter iOS startet der Weichzeichner an, sobald Thema folgen aus ist.</p><h2 id="vorschau" tabindex="-1">Vorschau <a class="header-anchor" href="#vorschau" aria-label="Permalink to &quot;Vorschau&quot;">​</a></h2><p><strong>Vorschau</strong> oben rechts öffnet ein Beispiel: Hintergrund ist die weibliche Beispielkarte der aktuellen Sprache, dazu Beispieldialog und Eingabe. Die letzte Nachricht ist von der KI und zeigt Fortsetzen und Smart Reply, sendet aber nicht. Die Eingabe sendet ebenfalls nicht. Die linke Schaltfläche und Einstellungen tun nichts.</p><h2 id="siehe-auch" tabindex="-1">Siehe auch <a class="header-anchor" href="#siehe-auch" aria-label="Permalink to &quot;Siehe auch&quot;">​</a></h2><ul><li><a href="./chat">Chat</a>: Bubble-Menü und Chat-Einstellungen der Sitzung</li><li><a href="./settings">Einstellungen</a>: Design und Schrift</li></ul>',15)])])}const E=i(o,[["render",h]]);export{m as __pageData,E as default};
